-- === 0030_task_urgent_since.sql ===
-- Tracks when a task's priority most recently became 'urgent', so the UI
-- can flag tasks that have been urgent for more than 24h. Maintained by a
-- trigger rather than app code so it stays correct regardless of which
-- code path changes priority (TaskForm create/edit, future paths, etc).

alter table public.tasks add column urgent_since timestamptz;

update public.tasks set urgent_since = created_at where priority = 'urgent';

create or replace function public.track_urgent_since()
returns trigger
language plpgsql
as $$
begin
  if new.priority = 'urgent' and (old is null or old.priority is distinct from 'urgent') then
    new.urgent_since = now();
  elsif new.priority <> 'urgent' then
    new.urgent_since = null;
  end if;
  return new;
end;
$$;

create trigger tasks_track_urgent_since
  before insert or update of priority on public.tasks
  for each row execute function public.track_urgent_since();

-- === 0031_client_credentials.sql ===
-- Admin-only vault of client platform logins (Instagram, Meta Business
-- Suite, Google Ads, etc.) — master-key only, same RLS shape as
-- company_transactions. Not encrypted at rest, same security model as the
-- rest of this admin panel's sensitive data (salaries, finances): gated
-- entirely by RLS + master-key checks, not field-level encryption.

create table public.client_credentials (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients(id) on delete cascade,
  platform text not null,
  login text not null,
  password text not null,
  auth_code text,
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index client_credentials_client_id_idx on public.client_credentials(client_id);

create trigger client_credentials_set_updated_at
  before update on public.client_credentials
  for each row execute function public.set_updated_at();

alter table public.client_credentials enable row level security;

create policy "client_credentials_all_master_key" on public.client_credentials
  for all using (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  ) with check (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  );

-- === 0032_client_questions.sql ===
-- Client Q&A: clients ask questions from the portal, any team member can
-- answer. Mirrors client_reports' RLS shape: clients see/insert only their
-- own (accessible_client_ids()-scoped) questions and can't set the answer
-- fields themselves; team members see everything and are the only ones who
-- can answer (update) or delete.

create table public.client_questions (
  id uuid primary key default gen_random_uuid(),
  client_id uuid not null references public.clients(id) on delete cascade,
  asked_by uuid references public.profiles(id),
  question text not null,
  answer text,
  answered_by uuid references public.profiles(id),
  answered_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index client_questions_client_id_idx on public.client_questions(client_id);
create index client_questions_unanswered_idx on public.client_questions(answered_at) where answered_at is null;

create trigger client_questions_set_updated_at
  before update on public.client_questions
  for each row execute function public.set_updated_at();

alter table public.client_questions enable row level security;

create policy "client_questions_select_authenticated" on public.client_questions
  for select using (
    public.current_role() <> 'client' or client_id in (select public.accessible_client_ids())
  );

create policy "client_questions_insert_client" on public.client_questions
  for insert with check (
    public.current_role() = 'client'
    and client_id in (select public.accessible_client_ids())
    and asked_by = auth.uid()
    and answer is null
    and answered_by is null
    and answered_at is null
  );

create policy "client_questions_update_team" on public.client_questions
  for update using (public.current_role() <> 'client')
  with check (public.current_role() <> 'client');

create policy "client_questions_delete_leader" on public.client_questions
  for delete using (public.current_role() = 'team_leader');

-- === 0033_task_multi_assignees.sql ===
-- Multiple assignees per task. tasks.assignee_id stays populated as the
-- "primary" assignee (first person chosen) so every existing single-assignee
-- consumer (calendar sync, quota, AI auto-assign, salary/workload role
-- counts) keeps working unchanged; task_assignees is the full list and is
-- always a superset that includes the primary.

create table public.task_assignees (
  task_id uuid not null references public.tasks(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (task_id, profile_id)
);

create index task_assignees_profile_id_idx on public.task_assignees(profile_id);

alter table public.task_assignees enable row level security;

create policy "task_assignees_select_authenticated" on public.task_assignees
  for select using (
    exists (
      select 1 from public.tasks t
      where t.id = task_assignees.task_id
        and (public.current_role() <> 'client' or t.client_id in (select public.accessible_client_ids()))
    )
  );

create policy "task_assignees_insert_team" on public.task_assignees
  for insert with check (public.current_role() <> 'client');

create policy "task_assignees_delete_own_or_leader" on public.task_assignees
  for delete using (
    public.current_role() = 'team_leader'
    or exists (
      select 1 from public.task_assignees ta2
      where ta2.task_id = task_assignees.task_id and ta2.profile_id = auth.uid()
    )
  );

-- Backfill: every task that already has a primary assignee gets a matching row.
insert into public.task_assignees (task_id, profile_id)
select id, assignee_id from public.tasks where assignee_id is not null
on conflict do nothing;

-- A secondary (non-primary) assignee should be able to update task status
-- too, same as the primary assignee already could.
drop policy "tasks_update_own_or_leader" on public.tasks;
create policy "tasks_update_own_or_leader" on public.tasks
  for update using (
    public.current_role() = 'team_leader'
    or assignee_id = auth.uid()
    or exists (
      select 1 from public.task_assignees ta
      where ta.task_id = tasks.id and ta.profile_id = auth.uid()
    )
  );

-- === 0034_push_notifications.sql ===
-- Web Push notifications: a member gets notified when assigned a task,
-- once they've subscribed from an installed (home-screen) PWA.

create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  created_at timestamptz not null default now()
);

create index push_subscriptions_profile_id_idx on public.push_subscriptions(profile_id);

alter table public.push_subscriptions enable row level security;

create policy "push_subscriptions_own" on public.push_subscriptions
  for all using (profile_id = auth.uid()) with check (profile_id = auth.uid());

-- This project has never used Supabase's Database Webhooks feature, so the
-- supabase_functions.http_request() convenience wrapper it normally
-- provisions doesn't exist here. pg_net (the extension that wrapper is
-- built on) is available directly, so the trigger is built on that instead.
--
-- The function below hardcodes THIS project's own Edge Function URL and
-- shared secret, so it cannot be replayed as-is into a white-label
-- tenant's project (it would both leak this secret and call the wrong
-- endpoint) — excluded from scripts/build-tenant-schema.mjs's output via
-- the trailing markers below. Push notifications are a documented v1 gap
-- for white-label tenants; the push_subscriptions table above still gets
-- created for them, ready to wire up if they deploy their own Edge
-- Function later.

-- === 0035_fix_tasks_rls_recursion.sql ===
-- tasks_update_own_or_leader (added in 0033) checks task_assignees inline,
-- and task_assignees' own select policy checks back into tasks — a genuine
-- two-table RLS cycle that trips Postgres's recursion guard on any UPDATE
-- to tasks ("infinite recursion detected in policy for relation tasks").
-- Same fix already used everywhere else in this schema for this exact
-- problem (current_role, current_client_id, accessible_client_ids): wrap
-- the cross-table check in a security definer function, which — like
-- those — runs as the table owner and so isn't itself subject to
-- task_assignees' RLS, breaking the cycle.

create or replace function public.is_task_assignee(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.task_assignees
    where task_id = p_task_id and profile_id = auth.uid()
  )
$$;

drop policy "tasks_update_own_or_leader" on public.tasks;
create policy "tasks_update_own_or_leader" on public.tasks
  for update using (
    public.current_role() = 'team_leader'
    or assignee_id = auth.uid()
    or public.is_task_assignee(id)
  );

-- === 0036_special_tasks.sql ===
-- Special (bounty) tasks: master-key only creates them with a payout
-- attached; they sit open (unassigned) until any team member claims one,
-- delivers it (status -> review), and the admin approves it, choosing an
-- instant payout or adding it to the member's running monthly total.

alter table public.tasks add column is_special boolean not null default false;
alter table public.tasks add column payout_amount numeric(10,2);
alter table public.tasks add column payout_method text check (payout_method in ('instant', 'monthly_invoice'));
alter table public.tasks add column payout_approved_by uuid references public.profiles(id);
alter table public.tasks add column payout_approved_at timestamptz;
alter table public.tasks add column payout_paid boolean not null default false;
alter table public.tasks add column payout_paid_at timestamptz;

-- Claiming an open special task needs to work for any team member, but
-- tasks_update_own_or_leader only allows the leader to touch a task with
-- no assignee yet. Rather than loosen that policy, a narrow security
-- definer RPC does just the one safe thing: assign an unclaimed special
-- task to whoever calls it.
create or replace function public.claim_special_task(p_task_id uuid)
returns public.tasks
language plpgsql
security definer
set search_path = public
as $$
declare
  result public.tasks;
begin
  if public.current_role() = 'client' then
    raise exception 'Not allowed';
  end if;

  update public.tasks
  set assignee_id = auth.uid()
  where id = p_task_id and is_special and assignee_id is null and not archived
  returning * into result;

  if result.id is null then
    raise exception 'This task is no longer available to claim';
  end if;

  insert into public.task_assignees (task_id, profile_id)
  values (p_task_id, auth.uid())
  on conflict do nothing;

  return result;
end;
$$;

revoke all on function public.claim_special_task(uuid) from public;
grant execute on function public.claim_special_task(uuid) to authenticated;

-- Creating a special task, or changing its special/payout attributes, is
-- master-key only (same trust boundary as company_transactions, which the
-- approval step writes to) — everything else about a task (status,
-- assignee, title, ...) stays governed by the existing RLS policies, so
-- claiming and delivering by a regular member still goes through fine.
create or replace function public.enforce_special_task_master_key()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  is_master boolean;
begin
  is_master := (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com';
  if is_master then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.is_special then
      raise exception 'Only the admin can create special tasks';
    end if;
    return new;
  end if;

  if new.is_special is distinct from old.is_special
    or new.payout_amount is distinct from old.payout_amount
    or new.payout_method is distinct from old.payout_method
    or new.payout_approved_by is distinct from old.payout_approved_by
    or new.payout_approved_at is distinct from old.payout_approved_at
    or new.payout_paid is distinct from old.payout_paid
    or new.payout_paid_at is distinct from old.payout_paid_at
  then
    raise exception 'Only the admin can modify special task payout details';
  end if;

  return new;
end;
$$;

create trigger tasks_enforce_special_master_key
  before insert or update on public.tasks
  for each row execute function public.enforce_special_task_master_key();

-- === 0037_task_attachments.sql ===
-- File attachments on tasks — any team member or the owning client can
-- attach a file (reference material, a graphic element to include, or
-- finished work), capped at 50MB per file by the storage bucket itself.
-- Access mirrors tasks' own visibility rule exactly (staff see everything,
-- clients only their own accessible tasks) via a shared helper function so
-- both the table and the storage bucket enforce the same boundary.

create or replace function public.can_access_task(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.tasks t
    where t.id = p_task_id
      and (public.current_role() <> 'client' or t.client_id in (select public.accessible_client_ids()))
  )
$$;

create table public.task_attachments (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.tasks(id) on delete cascade,
  uploaded_by uuid references public.profiles(id),
  category text not null check (category in ('reference', 'graphic_element', 'finished_work')),
  storage_path text not null,
  file_name text not null,
  file_size bigint not null,
  mime_type text,
  created_at timestamptz not null default now()
);

create index task_attachments_task_id_idx on public.task_attachments(task_id);

alter table public.task_attachments enable row level security;

create policy "task_attachments_select" on public.task_attachments
  for select using (public.can_access_task(task_id));

create policy "task_attachments_insert" on public.task_attachments
  for insert with check (auth.uid() is not null and public.can_access_task(task_id));

-- Uploader can remove their own file; a leader can moderate any of them.
create policy "task_attachments_delete" on public.task_attachments
  for delete using (uploaded_by = auth.uid() or public.current_role() = 'team_leader');

insert into storage.buckets (id, name, public, file_size_limit)
values ('task-attachments', 'task-attachments', false, 52428800);

-- Path convention: {task_id}/{category}/{timestamp}-{filename} — lets the
-- storage policies below parse the task id straight out of the path via
-- storage.foldername() and defer to the same can_access_task() check.
create policy "task_attachments_storage_select" on storage.objects
  for select using (
    bucket_id = 'task-attachments'
    and public.can_access_task((storage.foldername(name))[1]::uuid)
  );

create policy "task_attachments_storage_insert" on storage.objects
  for insert with check (
    bucket_id = 'task-attachments'
    and public.can_access_task((storage.foldername(name))[1]::uuid)
  );

create policy "task_attachments_storage_delete" on storage.objects
  for delete using (
    bucket_id = 'task-attachments'
    and (owner = auth.uid() or public.current_role() = 'team_leader')
  );

alter publication supabase_realtime add table public.task_attachments;

-- === 0038_tasks_update_any_staff.sql ===
-- Any staff member (not just the leader, the assignee, or a co-assignee)
-- should be able to edit any task — the assignment is a work-routing
-- signal, not an access boundary. Deletion stays leader-only via the
-- existing tasks_delete_leader_only policy; this only loosens UPDATE,
-- and mirrors tasks_select_authenticated's own staff-vs-client split so
-- clients still get no direct update access through this policy.

drop policy "tasks_update_own_or_leader" on public.tasks;

create policy "tasks_update_staff" on public.tasks
  for update using (public.current_role() <> 'client');

-- === 0039_fix_task_assignees_recursion.sql ===
-- task_assignees_delete_own_or_leader queried task_assignees from inside
-- its own DELETE policy (EXISTS ... FROM task_assignees ta2 ...), tripping
-- Postgres's RLS recursion guard ("infinite recursion detected in policy
-- for relation task_assignees") on every save in TaskForm, since it always
-- deletes-then-reinserts task_assignees for an existing task. Same failure
-- class as 0035, just on this table instead of tasks — same fix: defer to
-- the existing is_task_assignee() security definer helper, which runs as
-- the table owner and so isn't itself subject to this table's RLS.
--
-- Also widen both this policy and task_steps' delete policy from
-- "leader or the single owner" to "any staff member", matching
-- tasks_update_staff (0038) — a member editing someone else's task needs
-- to be able to replace its steps and assignees too, not just its fields.

drop policy "task_assignees_delete_own_or_leader" on public.task_assignees;

create policy "task_assignees_delete_staff" on public.task_assignees
  for delete using (public.current_role() <> 'client');

drop policy "task_steps_delete_leader_or_owner" on public.task_steps;

create policy "task_steps_delete_staff" on public.task_steps
  for delete using (public.current_role() <> 'client');

-- === 0040_task_batch_id.sql ===
-- Correlates the N sibling task rows created together by the "All
-- {group}" bulk-create flow in TaskForm, so the pipeline view can display
-- them as a single collapsible row (e.g. "All JØNK") instead of N separate
-- ones — while the underlying rows stay independent so per-location
-- credit quotas and each location's own client-portal view keep working
-- exactly as before.

alter table public.tasks add column batch_id uuid;
create index tasks_batch_id_idx on public.tasks(batch_id) where batch_id is not null;

-- === 0043_meeting_task_calendar_sync.sql ===
-- Auto-syncs "meeting" content-type tasks into calendar_events, one row
-- per assignee (mirrors the existing meetup pattern in
-- confirm_meetup_if_all_accepted). The task stays the source of truth:
-- editing a meeting task's title/deadline/assignees re-syncs the linked
-- calendar_events rows. Editing the calendar event directly still works
-- (unchanged EventForm edit flow), but a later edit to the source task
-- will overwrite it again — an accepted tradeoff, not a full
-- bidirectional sync.

alter table public.calendar_events
  drop constraint calendar_events_task_id_fkey;

alter table public.calendar_events
  add constraint calendar_events_task_id_fkey
    foreign key (task_id) references public.tasks(id) on delete cascade;

create unique index calendar_events_task_assignee_key
  on public.calendar_events (task_id, assignee_id)
  where task_id is not null;

create or replace function public.sync_meeting_calendar_events()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.task_type = 'meeting' and new.deadline is not null and new.archived = false then
    insert into public.calendar_events
      (client_id, task_id, assignee_id, title, event_type, starts_at, ends_at, source, created_by)
    select new.client_id, new.id, ta.profile_id, new.title, 'meeting', new.deadline,
           new.deadline + interval '1 hour', new.source, new.created_by
    from public.task_assignees ta
    where ta.task_id = new.id
    on conflict (task_id, assignee_id) where task_id is not null
    do update set
      client_id = excluded.client_id,
      title = excluded.title,
      starts_at = excluded.starts_at,
      ends_at = excluded.ends_at,
      source = excluded.source;
  else
    delete from public.calendar_events where task_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists tasks_sync_meeting_calendar_events on public.tasks;
create trigger tasks_sync_meeting_calendar_events
  after insert or update on public.tasks
  for each row
  execute function public.sync_meeting_calendar_events();

create or replace function public.sync_meeting_calendar_event_for_assignee()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks%rowtype;
begin
  select * into v_task from public.tasks where id = new.task_id;
  if v_task.task_type = 'meeting' and v_task.deadline is not null and v_task.archived = false then
    insert into public.calendar_events
      (client_id, task_id, assignee_id, title, event_type, starts_at, ends_at, source, created_by)
    values
      (v_task.client_id, v_task.id, new.profile_id, v_task.title, 'meeting', v_task.deadline,
       v_task.deadline + interval '1 hour', v_task.source, v_task.created_by)
    on conflict (task_id, assignee_id) where task_id is not null
    do update set
      client_id = excluded.client_id,
      title = excluded.title,
      starts_at = excluded.starts_at,
      ends_at = excluded.ends_at,
      source = excluded.source;
  end if;
  return new;
end;
$$;

drop trigger if exists task_assignees_sync_meeting_calendar_event on public.task_assignees;
create trigger task_assignees_sync_meeting_calendar_event
  after insert on public.task_assignees
  for each row
  execute function public.sync_meeting_calendar_event_for_assignee();

create or replace function public.cleanup_meeting_calendar_event_for_assignee()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.calendar_events where task_id = old.task_id and assignee_id = old.profile_id;
  return old;
end;
$$;

drop trigger if exists task_assignees_cleanup_meeting_calendar_event on public.task_assignees;
create trigger task_assignees_cleanup_meeting_calendar_event
  after delete on public.task_assignees
  for each row
  execute function public.cleanup_meeting_calendar_event_for_assignee();

-- Backfill: meeting tasks created before this migration existed.
insert into public.calendar_events
  (client_id, task_id, assignee_id, title, event_type, starts_at, ends_at, source, created_by)
select t.client_id, t.id, ta.profile_id, t.title, 'meeting', t.deadline,
       t.deadline + interval '1 hour', t.source, t.created_by
from public.tasks t
join public.task_assignees ta on ta.task_id = t.id
where t.task_type = 'meeting' and t.deadline is not null and t.archived = false
on conflict (task_id, assignee_id) where task_id is not null do nothing;

-- === 0044_calendar_event_group.sql ===
-- Lets a calendar event have multiple assignees. Same shape as the
-- meeting-task sync (0043): one calendar_events row per assignee, tied
-- together by a shared event_group_id instead of a separate join table —
-- keeps per-assignee conflict-checking, color-coding, and RLS exactly as
-- they are today, since each row still carries its own assignee_id.
--
-- Every existing row gets its own distinct event_group_id (a group of
-- one), so single-assignee events are unaffected.

alter table public.calendar_events
  add column event_group_id uuid not null default gen_random_uuid();

create unique index calendar_events_group_assignee_key
  on public.calendar_events (event_group_id, assignee_id);

-- Any staff member (not just the leader or the specific assignee) needs
-- to be able to add/remove OTHER people as co-assignees on an event —
-- mirrors tasks_update_staff (0038)'s same reasoning: assignment is a
-- work-routing signal, not an access boundary. Delete is widened too,
-- since removing a co-assignee from an event is a delete of their row.
drop policy "calendar_events_insert_own_or_leader" on public.calendar_events;
drop policy "calendar_events_update_own_or_leader" on public.calendar_events;
drop policy "calendar_events_delete_own_or_leader" on public.calendar_events;

create policy "calendar_events_insert_staff" on public.calendar_events
  for insert with check (public.current_role() <> 'client');
create policy "calendar_events_update_staff" on public.calendar_events
  for update using (public.current_role() <> 'client');
create policy "calendar_events_delete_staff" on public.calendar_events
  for delete using (public.current_role() <> 'client');

-- Task-synced meeting events (0043) should group the same way: a task's
-- own id is already a stable per-task uuid, so reuse it directly as the
-- event_group_id instead of generating a fresh one per assignee — that
-- way dragging one location's synced meeting on the calendar moves it
-- for every assignee on that task, not just the one that was dragged.
update public.calendar_events set event_group_id = task_id where task_id is not null;

create or replace function public.sync_meeting_calendar_events()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.task_type = 'meeting' and new.deadline is not null and new.archived = false then
    insert into public.calendar_events
      (client_id, task_id, event_group_id, assignee_id, title, event_type, starts_at, ends_at, source, created_by)
    select new.client_id, new.id, new.id, ta.profile_id, new.title, 'meeting', new.deadline,
           new.deadline + interval '1 hour', new.source, new.created_by
    from public.task_assignees ta
    where ta.task_id = new.id
    on conflict (task_id, assignee_id) where task_id is not null
    do update set
      client_id = excluded.client_id,
      title = excluded.title,
      starts_at = excluded.starts_at,
      ends_at = excluded.ends_at,
      source = excluded.source;
  else
    delete from public.calendar_events where task_id = new.id;
  end if;
  return new;
end;
$$;

create or replace function public.sync_meeting_calendar_event_for_assignee()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_task public.tasks%rowtype;
begin
  select * into v_task from public.tasks where id = new.task_id;
  if v_task.task_type = 'meeting' and v_task.deadline is not null and v_task.archived = false then
    insert into public.calendar_events
      (client_id, task_id, event_group_id, assignee_id, title, event_type, starts_at, ends_at, source, created_by)
    values
      (v_task.client_id, v_task.id, v_task.id, new.profile_id, v_task.title, 'meeting', v_task.deadline,
       v_task.deadline + interval '1 hour', v_task.source, v_task.created_by)
    on conflict (task_id, assignee_id) where task_id is not null
    do update set
      client_id = excluded.client_id,
      title = excluded.title,
      starts_at = excluded.starts_at,
      ends_at = excluded.ends_at,
      source = excluded.source;
  end if;
  return new;
end;
$$;

-- === 0045_task_client_group.sql ===
-- A "{Group} (ALL)" task is now a single row fulfilled by one location
-- (chosen by available credit, see app/api/tasks/pick-group-client), not
-- a copy created at every location in the group. client_group_id marks a
-- task as belonging to the whole group for display purposes ("JØNK
-- (ALL)" in the Pipeline) while client_id still points at the one
-- location actually doing the work, so credit/quota tracking and portal
-- visibility are unaffected.
alter table public.tasks
  add column client_group_id uuid references public.client_groups(id);

-- === 0046_group_all_pseudo_client.sql ===
-- Replaces the client_group_id tagging approach (a task pinned to one real
-- location, tagged as "really for the whole group") with an actual pseudo
-- client per group, e.g. "JØNK (ALL)". A task assigned to it is just one
-- normal task under one normal client_id — no more duplicate-looking rows
-- per location. Credit is still deducted from a real location, tracked via
-- the new tasks.credit_client_id column instead of client_id itself.

alter table public.clients add column is_group_all boolean not null default false;
alter table public.client_groups add column all_client_id uuid references public.clients(id) unique;
alter table public.tasks add column credit_client_id uuid references public.clients(id);

-- Grant client-master-account portal logins visibility into their group's
-- pseudo client too (it deliberately has clients.group_id = null so it
-- never shows up as a "member" in ordinary group-membership lookups
-- throughout the app — this is the one place that needs an explicit
-- carve-out for it).
create or replace function public.accessible_client_ids()
returns setof uuid language sql stable security definer set search_path = public as $$
  select id from public.clients
  where id = public.current_client_id()
     or group_id = public.current_client_group_id()
     or id = (select all_client_id from public.client_groups where id = public.current_client_group_id())
$$;

-- Backfill: create the "(ALL)" pseudo client for every existing group, and
-- migrate any tasks already tagged via the old client_group_id column onto
-- the new model — credit stays with whichever real location was picked at
-- the time (client_id), the task's own client becomes the group's pseudo
-- client.
do $$
declare
  g record;
  new_client_id uuid;
begin
  for g in select id, name from public.client_groups where all_client_id is null loop
    insert into public.clients (name, monthly_credit_limit, is_group_all)
    values (g.name || ' (ALL)', null, true)
    returning id into new_client_id;

    update public.client_groups set all_client_id = new_client_id where id = g.id;

    update public.tasks
    set credit_client_id = client_id,
        client_id = new_client_id
    where client_group_id = g.id;
  end loop;
end $$;

alter table public.tasks drop column client_group_id;

-- === 0047_social_post_plan.sql ===
-- Post Plan: a social-media content calendar, separate from the client
-- task pipeline. Each post is scheduled for a specific date/time, color
-- coded by media type (video/image/graphic/collab/campaign), credits
-- whichever team members were involved, and can carry files. Staff-only —
-- clients never see this, it's the agency's own publishing calendar, not
-- a per-client deliverable.

create table public.social_posts (
  id uuid primary key default gen_random_uuid(),
  platform text not null check (platform in (
    'instagram', 'tiktok', 'facebook', 'youtube', 'linkedin', 'x', 'snapchat', 'pinterest', 'threads', 'other'
  )),
  media_type text not null check (media_type in ('video', 'image', 'graphic', 'collab', 'campaign')),
  caption text,
  tag_handles text,
  suggested_song text,
  post_at timestamptz not null,
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index social_posts_post_at_idx on public.social_posts(post_at);

create trigger social_posts_set_updated_at
  before update on public.social_posts
  for each row execute function public.set_updated_at();

create table public.social_post_credits (
  post_id uuid not null references public.social_posts(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  primary key (post_id, profile_id)
);

create table public.social_post_attachments (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.social_posts(id) on delete cascade,
  uploaded_by uuid references public.profiles(id),
  storage_path text not null,
  file_name text not null,
  file_size bigint not null,
  mime_type text,
  created_at timestamptz not null default now()
);

create index social_post_attachments_post_id_idx on public.social_post_attachments(post_id);

alter table public.social_posts enable row level security;
alter table public.social_post_credits enable row level security;
alter table public.social_post_attachments enable row level security;

create policy "social_posts_select_staff" on public.social_posts
  for select using (public.current_role() <> 'client');

create policy "social_posts_insert_staff" on public.social_posts
  for insert with check (public.current_role() <> 'client' and created_by = auth.uid());

create policy "social_posts_update_staff" on public.social_posts
  for update using (public.current_role() <> 'client');

create policy "social_posts_delete_leader_only" on public.social_posts
  for delete using (public.current_role() = 'team_leader');

create policy "social_post_credits_select_staff" on public.social_post_credits
  for select using (public.current_role() <> 'client');

create policy "social_post_credits_insert_staff" on public.social_post_credits
  for insert with check (public.current_role() <> 'client');

create policy "social_post_credits_delete_staff" on public.social_post_credits
  for delete using (public.current_role() <> 'client');

create policy "social_post_attachments_select_staff" on public.social_post_attachments
  for select using (public.current_role() <> 'client');

create policy "social_post_attachments_insert_staff" on public.social_post_attachments
  for insert with check (public.current_role() <> 'client' and auth.uid() is not null);

create policy "social_post_attachments_delete" on public.social_post_attachments
  for delete using (uploaded_by = auth.uid() or public.current_role() = 'team_leader');

insert into storage.buckets (id, name, public, file_size_limit)
values ('social-post-attachments', 'social-post-attachments', false, 52428800);

create policy "social_post_attachments_storage_select" on storage.objects
  for select using (
    bucket_id = 'social-post-attachments' and public.current_role() <> 'client'
  );

create policy "social_post_attachments_storage_insert" on storage.objects
  for insert with check (
    bucket_id = 'social-post-attachments' and public.current_role() <> 'client'
  );

create policy "social_post_attachments_storage_delete" on storage.objects
  for delete using (
    bucket_id = 'social-post-attachments'
    and (owner = auth.uid() or public.current_role() = 'team_leader')
  );

alter publication supabase_realtime add table public.social_posts;
alter publication supabase_realtime add table public.social_post_credits;
alter publication supabase_realtime add table public.social_post_attachments;

-- Push-notify the admin (nasir@thequickstyle.com) whenever a file is
-- uploaded to a post — mirrors notify_task_assignment's pg_net + Edge
-- Function pattern (0034_push_notifications.sql). Hardcodes this
-- project's own function URL/secret, so excluded from the white-label
-- tenant schema build like that trigger is.

-- === 0048_social_post_client_scope.sql ===
-- Lets a client view (never edit) Post Plan posts tagged to their own
-- client/group — mirrors the accessible_client_ids() scoping already used
-- everywhere else client-portal-facing. Insert/update/delete stay
-- staff-only (untouched), so "view" is enforced structurally, not just by
-- hiding UI.

alter table public.social_posts add column client_id uuid references public.clients(id);

create index social_posts_client_id_idx on public.social_posts(client_id);

drop policy "social_posts_select_staff" on public.social_posts;
create policy "social_posts_select" on public.social_posts
  for select using (
    public.current_role() <> 'client' or client_id in (select public.accessible_client_ids())
  );

create or replace function public.can_view_post(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.social_posts p
    where p.id = p_post_id
      and (public.current_role() <> 'client' or p.client_id in (select public.accessible_client_ids()))
  )
$$;

drop policy "social_post_credits_select_staff" on public.social_post_credits;
create policy "social_post_credits_select" on public.social_post_credits
  for select using (public.can_view_post(post_id));

drop policy "social_post_attachments_select_staff" on public.social_post_attachments;
create policy "social_post_attachments_select" on public.social_post_attachments
  for select using (public.can_view_post(post_id));

drop policy "social_post_attachments_storage_select" on storage.objects;
create policy "social_post_attachments_storage_select" on storage.objects
  for select using (
    bucket_id = 'social-post-attachments'
    and public.can_view_post((storage.foldername(name))[1]::uuid)
  );

-- === 0049_social_post_type.sql ===
-- Post format (story/reel/carousel/post) alongside media type — separate
-- axis, e.g. a video can be posted as either a Reel or a regular feed post.

alter table public.social_posts
  add column post_type text not null default 'post'
  check (post_type in ('story', 'reel', 'carousel', 'post'));

-- === 0050_campaigns.sql ===
-- Ad campaigns per client — budget/spend/ROAS tracking, multi-channel
-- distribution, and a linked table for campaign creative (images/posters),
-- backed by Supabase Storage. Staff-only for now (no client-portal
-- visibility yet — that can follow the same client_id + RLS pattern
-- social_posts uses, in a later phase if wanted).

-- Drives the human-readable "CMP-00001" style code below. A raw sequence
-- (not identity-on-the-column) so the code can be formatted with a prefix
-- and zero-padding via the column default.
create sequence public.campaign_code_seq;

create table public.campaigns (
  id uuid primary key default gen_random_uuid(),
  code text not null unique default ('CMP-' || lpad(nextval('public.campaign_code_seq')::text, 5, '0')),
  client_id uuid not null references public.clients(id),
  name text not null,
  budget numeric(12, 2),
  ad_spend numeric(12, 2),
  roas numeric(10, 2),
  boost_location text,
  -- Free-form array (not CHECK-constrained) so new channels don't need a
  -- migration — validated against a constants list at the app layer,
  -- same convention as everywhere else options are UI-driven, not DB-enum.
  distribution_channels text[] not null default '{}',
  publication_date date,
  status text not null default 'draft'
    check (status in ('draft', 'scheduled', 'active', 'paused', 'completed', 'cancelled')),
  notes text,
  created_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index campaigns_client_id_idx on public.campaigns(client_id);

create trigger campaigns_set_updated_at
  before update on public.campaigns
  for each row execute function public.set_updated_at();

create table public.campaign_attachments (
  id uuid primary key default gen_random_uuid(),
  campaign_id uuid not null references public.campaigns(id) on delete cascade,
  uploaded_by uuid references public.profiles(id),
  storage_path text not null,
  file_name text not null,
  file_size bigint not null,
  mime_type text,
  created_at timestamptz not null default now()
);

create index campaign_attachments_campaign_id_idx on public.campaign_attachments(campaign_id);

alter table public.campaigns enable row level security;
alter table public.campaign_attachments enable row level security;

create policy "campaigns_select_staff" on public.campaigns
  for select using (public.current_role() <> 'client');

create policy "campaigns_insert_staff" on public.campaigns
  for insert with check (public.current_role() <> 'client');

create policy "campaigns_update_staff" on public.campaigns
  for update using (public.current_role() <> 'client');

create policy "campaigns_delete_leader_only" on public.campaigns
  for delete using (public.current_role() = 'team_leader');

create policy "campaign_attachments_select_staff" on public.campaign_attachments
  for select using (public.current_role() <> 'client');

create policy "campaign_attachments_insert_staff" on public.campaign_attachments
  for insert with check (public.current_role() <> 'client' and auth.uid() is not null);

create policy "campaign_attachments_delete" on public.campaign_attachments
  for delete using (uploaded_by = auth.uid() or public.current_role() = 'team_leader');

insert into storage.buckets (id, name, public, file_size_limit)
values ('campaign-attachments', 'campaign-attachments', false, 52428800);

create policy "campaign_attachments_storage_select" on storage.objects
  for select using (
    bucket_id = 'campaign-attachments' and public.current_role() <> 'client'
  );

create policy "campaign_attachments_storage_insert" on storage.objects
  for insert with check (
    bucket_id = 'campaign-attachments' and public.current_role() <> 'client'
  );

create policy "campaign_attachments_storage_delete" on storage.objects
  for delete using (
    bucket_id = 'campaign-attachments'
    and (owner = auth.uid() or public.current_role() = 'team_leader')
  );

alter publication supabase_realtime add table public.campaigns;
alter publication supabase_realtime add table public.campaign_attachments;

-- === 0051_campaigns_master_key_only.sql ===
-- Campaigns hold budget/ad-spend data and the admin page gating this
-- feature is master-key only (per Phase 2 scope) — tighten RLS to match,
-- same shape as client_credentials, so DB access mirrors the UI gate
-- instead of a broader "any staff" policy that a direct API call could
-- still exercise regardless of what the page shows.

drop policy "campaigns_select_staff" on public.campaigns;
drop policy "campaigns_insert_staff" on public.campaigns;
drop policy "campaigns_update_staff" on public.campaigns;
drop policy "campaigns_delete_leader_only" on public.campaigns;

create policy "campaigns_all_master_key" on public.campaigns
  for all using (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  ) with check (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  );

drop policy "campaign_attachments_select_staff" on public.campaign_attachments;
drop policy "campaign_attachments_insert_staff" on public.campaign_attachments;
drop policy "campaign_attachments_delete" on public.campaign_attachments;

create policy "campaign_attachments_all_master_key" on public.campaign_attachments
  for all using (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  ) with check (
    (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  );

drop policy "campaign_attachments_storage_select" on storage.objects;
drop policy "campaign_attachments_storage_insert" on storage.objects;
drop policy "campaign_attachments_storage_delete" on storage.objects;

create policy "campaign_attachments_storage_master_key" on storage.objects
  for all using (
    bucket_id = 'campaign-attachments'
    and (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  ) with check (
    bucket_id = 'campaign-attachments'
    and (select email from public.profiles where id = auth.uid()) = 'nasir@thequickstyle.com'
  );

